"""Handover package generation (JSON and Markdown).

The package only restates source data and engine findings. Nothing in it is
invented: empty sections are reported as empty.
"""

from __future__ import annotations

import json
import re
from datetime import datetime, timezone

from app import __version__
from app.models import (
    PENDING_REVIEW,
    STATUS_LABELS,
    AcceptanceRecord,
    AnalysisResult,
    Category,
    Handover,
    Insights,
    ItemState,
    KnowledgeItem,
)
from app.rules import Rules

DISCLAIMER = (
    "Generated by ContextRelay AI, a local proof of concept. The readiness score is a configurable, "
    "rule-based heuristic - not a prediction or probability. Acceptance is a local application record: "
    "it is not a legally binding signature, not proof of identity and not a compliance certification."
)


def safe_filename(handover: Handover, revision: int, extension: str) -> str:
    """Download name built only from a restricted character set."""
    slug = re.sub(r"[^a-z0-9]+", "-", (handover.title or handover.id).lower()).strip("-")[:60] or "handover"
    extension = re.sub(r"[^a-z0-9]", "", extension.lower()) or "txt"
    return f"handover-{slug}-rev{int(revision)}.{extension}"


def build_package(
    handover: Handover,
    result: AnalysisResult,
    revision: int,
    rules: Rules,
    *,
    acceptance_status: str = PENDING_REVIEW,
    acceptance: AcceptanceRecord | None = None,
    insights: Insights | None = None,
    generated_at: str | None = None,
) -> dict:
    scenario = rules.for_scenario(handover.scenario)
    assessments = {a.category: a for a in result.assessments}
    knowledge = {}
    for category in Category:
        a = assessments[category]
        knowledge[category.value] = {
            "label": a.label,
            "required": a.required,
            "status": a.status.value,
            "status_label": STATUS_LABELS[a.status],
            "not_applicable_reason": a.reason,
            "items": [item.model_dump(mode="json", exclude={"category"}) for item in handover.items_in(category)],
        }
    return {
        "generated_at": generated_at or datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "generator": f"ContextRelay AI {__version__}",
        "disclaimer": DISCLAIMER,
        "rules_version": rules.version,
        "handover": {
            "id": handover.id,
            "revision": revision,
            "title": handover.title,
            "description": handover.description,
            "scenario": handover.scenario.value,
            "scenario_label": scenario.label,
            "outgoing_owner": handover.outgoing_owner,
            "receiving_owner": handover.receiving_owner,
            "target_date": handover.target_date,
        },
        "readiness": {
            "score": result.readiness_score,
            "status": result.readiness_status.value,
            "status_reason": result.status_reason,
            "blocking_gap_ids": result.blocking_gap_ids,
            "ownership_coverage_pct": result.ownership_coverage,
            "dimensions": [d.model_dump(mode="json") for d in result.dimensions],
        },
        "acceptance": {
            "status": acceptance_status,
            "record": acceptance.model_dump(mode="json") if acceptance else None,
        },
        "knowledge": knowledge,
        "gaps": [gap.model_dump(mode="json") for gap in result.gaps],
        "evidence_references": [
            {"item_id": item.id, "category": item.category.value, "title": item.title, "evidence": item.evidence}
            for item in handover.items
            if not rules.is_blank(item.evidence)
        ],
        "insights": insights.model_dump(mode="json") if insights else None,
    }


def render_json(package: dict) -> str:
    return json.dumps(package, indent=2, ensure_ascii=False)


def _cell(value: object) -> str:
    """Keep user text from breaking Markdown tables."""
    return str(value or "").replace("|", "\\|").replace("\r", " ").replace("\n", " ").strip() or "-"


def _item_line(item: dict) -> str:
    parts = [f"**{_cell(item['title'])}**"]
    if item["detail"]:
        parts.append(_cell(item["detail"]))
    meta = []
    if item["owner"]:
        meta.append(f"owner: {_cell(item['owner'])}")
    if item["due_date"]:
        meta.append(f"due: {_cell(item['due_date'])}")
    if item["critical"]:
        meta.append("critical")
    if item["escalation"]:
        meta.append("escalation contact")
    if item["state"] == ItemState.COMPLETED.value:
        meta.append("completed")
    if item["evidence"]:
        meta.append(f"evidence: {_cell(item['evidence'])}")
    if meta:
        parts.append(f"_({'; '.join(meta)})_")
    return f"- `{item['id']}` " + " - ".join(parts)


def _section(lines: list[str], title: str, block: dict, items: list[dict] | None = None) -> None:
    items = block["items"] if items is None else items
    lines.append(f"### {title}")
    lines.append(f"_Status: {block['status_label']}" + (" (required)_" if block["required"] else "_"))
    if block["not_applicable_reason"]:
        lines.append(f"Not applicable - reason given: {_cell(block['not_applicable_reason'])}")
    elif not items:
        lines.append("No entries provided.")
    lines.extend(_item_line(item) for item in items)
    lines.append("")


def render_markdown(package: dict) -> str:
    h, r, k = package["handover"], package["readiness"], package["knowledge"]
    lines = [
        f"# Handover Package: {_cell(h['title'])}",
        "",
        f"> {package['disclaimer']}",
        "",
        "| | |",
        "|---|---|",
        f"| Scenario | {h['scenario_label']} |",
        f"| Outgoing owner | {_cell(h['outgoing_owner'])} |",
        f"| Receiving owner | {_cell(h['receiving_owner'])} |",
        f"| Target handover date | {_cell(h['target_date'])} |",
        f"| Handover ID / revision | {h['id']} / {h['revision']} |",
        f"| Generated at (UTC) | {package['generated_at']} |",
        f"| Rules version | {package['rules_version']} |",
        "",
    ]
    if h["description"]:
        lines += [_cell(h["description"]), ""]

    lines += [
        "## Readiness",
        "",
        f"- **Readiness score:** {r['score']} / 100 (rule-based heuristic)",
        f"- **Readiness status:** {r['status']} - {r['status_reason']}",
        f"- **Acceptance status:** {package['acceptance']['status']}",
    ]
    if r["ownership_coverage_pct"] is not None:
        lines.append(f"- **Ownership coverage:** {r['ownership_coverage_pct']:.0f}% of open items have a new owner")
    record = package["acceptance"]["record"]
    if record:
        lines.append(
            f"- **Receiver decision:** {record['decision'].replace('_', ' ')} by \"{_cell(record['receiver'])}\" "
            f"on revision {record['revision']} at {record['created_at']}"
        )
        if record["note"]:
            lines.append(f"- **Decision note:** {_cell(record['note'])}")
        if record["acknowledged_gap_ids"]:
            lines.append("- **Accepted exceptions:** " + ", ".join(f"`{g}`" for g in record["acknowledged_gap_ids"]))
    lines += ["", "| Dimension | Weight | Score |", "|---|---|---|"]
    lines += [f"| {d['label']} | {d['weight']:g} | {d['score']} |" for d in r["dimensions"]]
    lines.append("")

    lines += ["## Handover Knowledge", ""]
    work = k[Category.ACTIVE_WORK.value]
    open_work = [i for i in work["items"] if i["state"] == ItemState.OPEN.value]
    done_work = [i for i in work["items"] if i["state"] == ItemState.COMPLETED.value]
    _section(lines, "Responsibilities", k[Category.RESPONSIBILITIES.value])
    _section(lines, "Work in progress", work, open_work)
    if done_work:
        _section(lines, "Completed / delivered work", work, done_work)
    _section(lines, "Decisions", k[Category.DECISIONS.value])
    _section(lines, "Dependencies", k[Category.DEPENDENCIES.value])
    _section(lines, "Deadlines", k[Category.DEADLINES.value])
    _section(lines, "Risks and blockers", k[Category.RISKS_BLOCKERS.value])
    _section(lines, "Ownership and contacts", k[Category.CONTACTS.value])
    _section(lines, "Access prerequisites", k[Category.ACCESS.value])
    _section(lines, "Documentation and resources", k[Category.DOCUMENTATION.value])
    _section(lines, "Outstanding questions", k[Category.OPEN_QUESTIONS.value])

    gaps = package["gaps"]
    lines += ["## Missing Information and Recommended Actions", ""]
    if gaps:
        lines += ["| Gap ID | Severity | Missing information | Recommended action | Responsible |", "|---|---|---|---|---|"]
        lines += [
            f"| `{_cell(g['id'])}` | {g['severity'].capitalize()} | {_cell(g['description'])} | "
            f"{_cell(g['recommended_action'])} | {_cell(g['responsible'])} |"
            for g in gaps
        ]
    else:
        lines.append("No gaps were detected by the configured rules.")
    lines.append("")

    lines += ["## Evidence References", ""]
    evidence = package["evidence_references"]
    if evidence:
        lines += [f"- `{e['item_id']}` {_cell(e['title'])}: {_cell(e['evidence'])}" for e in evidence]
        lines.append("")
        lines.append("_References are recorded as provided; the tool does not open or validate the referenced documents._")
    else:
        lines.append("No evidence references were provided.")
    lines.append("")

    insights = package.get("insights")
    if insights:
        lines += [f"## Suggestions ({insights['label']})", "", "_Suggestions are not verified facts._", "", insights["summary"], ""]
        lines += [f"- {question}" for question in insights["questions"]]
        lines.append("")
    return "\n".join(lines)
